mapper.select:
SELECT w.status, COUNT(*) AS count FROM work_order w WHERE TRUE

AND w.status = #{status}
GROUP BY w.status ORDER BY w.status

SELECT w.business_no, w.status, w.updated_at, COUNT(*) OVER () AS matched_count
FROM work_order w WHERE w.business_no ~ '^EVR-[0-9]{8}-[0-9]{6}$'

AND w.business_no = #{number}
AND w.status = #{status}
ORDER BY w.updated_at DESC, w.id DESC LIMIT 10
